 Certainly! Here's a JavaScript function that takes a sentence as an input and returns a new sentence where the order of the adjectives is reversed:
```javascript
function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words using a space as delimiter
  const words = sentence.split(' ');

  // Initialize empty arrays for adjectives and other words
  const adjectives = [];
  const otherWords = [];

  // Iterate through each word in the sentence and determine if it's an adjective or not
  for (const word of words) {
    const partOfSpeech = getPartOfSpeech(word);
    if (partOfSpeech === 'adjective') {
      adjectives.unshift(word);
    } else {
      otherWords.push(word);
    }
  }

  // Join the arrays back together into a sentence with the reversed order of adjectives
  return otherWords.join(' ') + ' ' + adjectives.join(' ') + ' ';
}
// Helper function to determine the part of speech of a word using a simple rule-based approach
function getPartOfSpeech(word) {
  // Simple rule-base for identifying adjectives based on their ending
  const lastLetter = word[word.length - 1];
  if (lastLetter === 'e' && word.length > 2 && /^[a-z]+[aeiou][bcdfghjklmnpqrstvwxyz]+$/.test(word.slice(0, -1))) {
    return 'adjective';
  }
  return 'other';
}
// Test the function with your example sentence
console.log(reverseAdjectiveOrder("Beautiful green trees are in the park"));
```
This function uses a helper function `getPartOfSpeech()` to identify adjectives based on their ending (words ending in `e` before the last letter are assumed to be adjectives). It then splits the sentence into words, separates the adjectives from the other words, and joins them back together in the reversed order. Note that this solution may not work

