```javascript
const axios = require('axios');

async function getAntonyms(word) {
  try {
    const response = await axios.get(`https://api.datamuse.com/words?rel_antonym=${word}`);
    return response.data;
  } catch (error) {
    console.log("Error fetching antonyms:", error);
  }
}

async function main() {
  const word = 'aesthetic';
  const antonyms = await getAntonyms(word);

  if (antonyms && antonyms.length > 0) {
    console.log('Antonyms for the word \'' + word + '\':');
    antonyms.forEach((anonym, index) => {
      console.log('\t', index + 1, '. ', anonym.word);
    });
  } else {
    console.log('No antonyms found for the word \'' + word + '\'.');
  }
}

main();
```

