import Text from 'react-text'; // Import the Text component from react-text

const removeWidows = (text) => {
  const lines = text.split(/(?<=\.|\?)\s+(?=[^\.]|$)/); // Split the text into lines based on periods and question marks

  return lines.map((line, index) => {
    if (index === lines.length - 1 && line.trim().length < 30) { // If it's the last line and it's too short
      return <Text key={index}>{line} {'\u00A0'.repeat(30 - line.length)}</Text>; // Add non-breaking spaces to fill up the line
    } else {
      return <Text key={index}>{line}</Text>; // Return the line as is for other cases
    }
  });
};
```

